INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (1, 'V1.0.0', '2026-07-08', 'major', '上线记录', '记录 Rainzt.cn 从零上线', '建站流程文章发布，明确博客的内容方向、页面结构和后续维护方式。', '["上线","建站","写作"]', '["发布《从零搭建 Rainzt.cn：我的个人博客上线流程》。","确定站点名称、作者身份、中文副题记和个人项目展示方向。","记录从本地开发、内容编写、静态构建到部署上线的完整路径。","这一天早于仓库首次提交，作为博客建设的公开起点保留。"]', '10,2', '2026-07-08 12:00:00', '2026-07-08 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (2, 'V1.0.1', '2026-07-09', 'feature', '建站起点', '朝朝听雨博客完成首次建站提交', '以 Astro 为底座的个人博客仓库建立，第一版页面、主题、内容和部署基础同时落地。', '["建站","Astro","Svelte","基础设施"]', '["建立朝朝听雨站点的 Astro + Svelte 项目结构，确定中文优先的个人博客定位。","落地首页、文章、归档、分类、标签、搜索、关于、友链、留言板、工具、相册和赞助等页面。","接入主题切换、壁纸、音乐、樱花、Live2D、Spine、图片优化和多语言基础。","建立 Markdown/MDX 内容目录、RSS/OG 输出、GitHub Actions 构建和部署工作流。"]', '1', '2026-07-09 12:00:00', '2026-07-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (3, 'V1.0.2', '2026-07-22', 'content', '文章与素材', '把 AI 项目和博客视觉一起放进站点', '新增 AI 无限画布项目记录和配套素材，首页、壁纸与个人资料开始形成统一叙事。', '["文章","AI","首页","素材"]', '["发布《AI 无限画布工作流：为电商主图生成搭建一套可编排的创作中枢》。","补充首页插画、壁纸缩略图和项目封面，建立更完整的个人项目入口。","整理文章搜索、Open Graph 和构建资源，为后续内容持续发布做准备。","更新部署文档和博客资料，让本地开发、预览与线上发布更容易交接。"]', '71,10,9,8,7,6', '2026-07-22 12:00:00', '2026-07-22 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (4, 'V1.1.0', '2026-07-24', 'minor', '布局与侧栏', '让宽屏和侧栏真正服务于阅读', '补充博客内容，调整宽屏布局，并让节日倒计时和侧栏交互更完整。', '["布局","侧栏","内容"]', '["完善文章、工具和项目内容的组织方式。","调整宽屏下的主内容宽度、侧栏间距和卡片比例。","优化节日倒计时的展示和状态更新。","继续修复侧栏组件、音乐、图库和欢迎提示之间的交互细节。"]', '', '2026-07-24 12:00:00', '2026-07-24 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (5, 'V1.2.0', '2026-07-25', 'feature', '项目与部署', '补齐页脚、项目展示和部署交接', '站点从个人实验页面进一步整理成可以交接、部署和持续维护的项目。', '["部署","页脚","项目"]', '["增加作品展示入口，并完善项目卡片和博客交互。","重新设计页脚角色、备案信息和文章封面比例。","编写 Rainzt 部署指南，记录构建、发布、回滚和目录维护方式。","保留现有视觉身份，同时减少页脚和文章卡片在不同尺寸下的变形。"]', '', '2026-07-25 12:00:00', '2026-07-25 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (6, 'V1.2.1', '2026-07-27', 'feature', '作品展示', '给项目展示页加入完整的动画叙事', '作品展示页增加动画实现说明，同时统一导航模式和移动端菜单。', '["作品展示","文章","导航"]', '["完善作品展示页的动画流程和视觉分镜。","发布《作品展示页动画实现原理》，记录滚动、转场和性能取舍。","统一导航栏在不同布局模式下的状态。","修复手机端导航菜单的展开、关闭和页面切换行为。"]', '23,11,10,8,7,3', '2026-07-27 12:00:00', '2026-07-27 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (7, 'V1.3.0', '2026-07-28', 'feature', '首页交互', '建立首页插画卡片和阅读进度', '首页开始拥有完整的插画卡片、作品介绍和导航阅读进度。', '["首页","导航","阅读体验"]', '["新增自适应插画首页卡片，并根据不同入口区分装饰。","加入平滑的首页作品介绍和退出转场。","导航栏增加文章阅读进度提示，阅读长文时能更直观看到位置。","调整文章封面并补充友链入口，为后续友链页面扩展打基础。"]', '32,11,9,8,6,3', '2026-07-28 12:00:00', '2026-07-28 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (8, 'V1.3.1', '2026-07-29', 'minor', '视觉打磨', '把首页转场和项目展示打磨到可长期使用', '连续调整首页引导、作品展示、文章封面、工具卡片和欢迎提示的视觉细节。', '["首页","作品展示","封面","动效"]', '["完善首页作品介绍的进场、停留、快门式转场和退出节奏。","增加项目和随笔的高保真封面，统一文章卡片的视觉权重。","优化工具页卡片结构，让工具名称、说明和操作入口更容易扫描。","调整欢迎提示的尺寸、位置和关闭行为，避免遮挡首页主要内容。"]', '42,32,9,7,6,3', '2026-07-29 12:00:00', '2026-07-29 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (9, 'V1.3.2', '2026-07-30', 'minor', '首页与移动端', '让首页更像一个人的入口', '首页加入更明确的个人化信息，同时修复手机端文章侧栏和页脚覆盖。', '["首页","移动端","博友圈"]', '["首页补充博友圈入口和个人化内容，让站点不只是一组文章卡片。","简化手机端文章侧栏，减少阅读时的层级干扰。","修复移动端文章页脚与内容区域的重叠问题。","继续微调首页引导和卡片间的装饰关系。"]', '42,32,13,8,7,3', '2026-07-30 12:00:00', '2026-07-30 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (10, 'V1.4.0', '2026-07-31', 'feature', '写作基础', '把博客写作体验整理成可持续的工作流', '文章内容处理、代码交互、音乐管理和 RSS/OG 输出一起完成一轮基础整理。', '["写作","文章","RSS","代码块"]', '["扩展文章内容配置，整理文章摘要、阅读时间和页面元数据的生成逻辑。","完善代码块交互、代码组切换和文章内链接处理。","整理音乐管理与页面切换时的生命周期，减少重复初始化。","同步 RSS、Open Graph 和文章元数据输出，为后续分享和搜索做准备。"]', '27,23,6,3,1', '2026-07-31 12:00:00', '2026-07-31 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (11, 'V1.4.1', '2026-08-01', 'minor', '导航适配', '让博客在紧凑屏幕上也保持清楚', '针对小尺寸笔记本和窄屏窗口调整导航、搜索和主内容的可用空间。', '["导航","响应式","搜索"]', '["优化导航栏在紧凑笔记本上的排列和折叠行为。","调整搜索入口与导航菜单的空间分配，避免按钮被挤出可视区域。","保留桌面端的主导航层级，同时让手机端继续使用横向可滚动的标签栏。"]', '19,7,6', '2026-08-01 12:00:00', '2026-08-01 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (12, 'V1.5.0', '2026-08-03', 'feature', '评论系统', '博客正式接入 Waline 评论', '文章评论和留言板开始使用 Waline，并补充评论邮件通知所需的站内模板。', '["Waline","留言板","邮件"]', '["接入 Waline 文章评论和留言板，保留昵称与邮箱校验。","加入评论邮件通知模板和装饰资源，统一评论区与博客视觉。","新增 WalineManager，用于处理 Astro/Swup 页面切换后的评论重新挂载。","评论服务的远程邮件投递仍需要在独立服务器侧部署和重启后确认。"]', '15,14,13', '2026-08-03 12:00:00', '2026-08-03 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (13, 'V1.5.1', '2026-08-04', 'fix', '评论体验', '修复移动评论面板的底部遮挡', '处理 Waline 表情选择器与手机端页脚之间的重叠，让评论操作区域保持完整。', '["Waline","移动端","修复"]', '["修复 Waline 表情选择器打开后遮挡底部内容的问题。","重新检查评论区在不同页面容器和移动端高度下的定位行为。","保持表情、输入框和提交按钮的原有操作顺序不变。"]', '28,15,14,12,9', '2026-08-04 12:00:00', '2026-08-04 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (14, 'V1.6.0', '2026-08-05', 'feature', '友链与评论', '友链开始形成自己的网络', '新增多组友链，并修复评论区 Emoji、站点资料和独立友链入口。', '["友链","Waline","数据"]', '["新增 Detached、Petrichor''s Blog 等友链，并补充茗辰原、小曦的园子等站点。","增加独立友链入口，修正 Rain 友链的名称、头像和元数据。","修复 Waline 未解析 Emoji 的显示问题，让评论内容不再出现原始编码。","统一友链配置中的标题、标签、权重和截图字段，为推荐排序做准备。"]', '36,19,17,15,13,12', '2026-08-05 12:00:00', '2026-08-05 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (15, 'V1.7.0', '2026-08-07', 'feature', '统计系统', '把访问统计接回真实的站点体验', '接入 Umami 统计和历史数据，并修复文章页 Waline 浏览量与云端追踪。', '["Umami","Waline","统计"]', '["新增 Umami 统计组件，支持文章浏览量、站点访问量和历史统计展示。","恢复 Waline 文章页的浏览量计数。","修复 Umami Cloud 追踪、共享指标和统计刷新后的数据同步。","为本地预览保留可解释的占位状态，不把本地构建误当成生产统计结果。"]', '36,18,14,13,12', '2026-08-07 12:00:00', '2026-08-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (16, 'V1.7.1', '2026-08-09', 'minor', '友链与首页', '补充友链入口，也让首页卡片更有区分度', '新增 MingBlog，接入 Travellings 官方图标，并调整首页卡片装饰层。', '["首页","友链","文章"]', '["新增 MingBlog 友链。","使用 Travellings 官方列车图标，替换不统一的导航视觉。","调整不同首页卡片的装饰逻辑，让项目、文章和友链入口更容易区分。","发布 Agent 电商自动化文章，补充博客的工程化内容线。"]', '44,42,32,23,20,19', '2026-08-09 12:00:00', '2026-08-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (17, 'V1.7.2', '2026-08-10', 'content', '友链入口', '把友链申请说明写清楚', '新增 Ditto 友链和友链申请提示，让外部站点更容易理解加入规则。', '["友链","申请"]', '["新增 Ditto 友链，并补充站点标签。","在友链页增加申请说明，明确需要准备的站点名称、头像、描述和链接信息。","继续统一友链卡片的标签和展示格式，减少不同来源资料的视觉差异。"]', '20,19,18,14', '2026-08-10 12:00:00', '2026-08-10 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (18, 'V1.7.3', '2026-08-11', 'minor', '评论与移动端', '让评论和设置在手机上更顺手', '补充 sssr7844 友链，并处理移动端设置面板和评论图片带来的拥挤。', '["移动端","Waline","友链"]', '["新增 sssr7844 友链。","优化移动端显示设置面板，减少窄屏下控件挤压和滚动困难。","关闭评论图片加载，降低评论区资源负担并保持留言内容聚焦。","继续使用统一的 Waline 生命周期处理页面切换后的评论重新初始化。"]', '36,28,20,19,17,15', '2026-08-11 12:00:00', '2026-08-11 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (19, 'V1.7.4', '2026-08-12', 'minor', '导航与友链', '调整导航入口，保留更轻的站点路径', '新增 s17、taozhiyy 友链，并移除不再需要的 Travellings 导航入口。', '["导航","友链"]', '["新增 s17 与 taozhiyy 友链。","移除 Travellings 导航链接，避免主导航承担过多外部入口。","保留已接入的官方列车图标资源，作为站点内容和友链体系中的历史视觉资产。"]', '20,18,17,16,14,11', '2026-08-12 12:00:00', '2026-08-12 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (20, 'V1.7.5', '2026-08-13', 'content', '友链扩展', '继续补充独立博客连接', '新增 styunlen 和 linzihao 两个友链站点，并完善对应卡片信息。', '["友链","配置"]', '["新增 styunlen 友链，补充头像、站点描述和标签。","新增 linzihao 友链，加入站点截图和展示顺序。","保持友链配置以真实站点资料为准，为后续推荐和 RSS 功能留下统一数据结构。"]', '22,21,19,18,17,16', '2026-08-13 12:00:00', '2026-08-13 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (21, 'V1.8.0', '2026-08-14', 'content', '文章与页面', '把个人故事和页面细节一起留下', '发布朝朝听雨主题文章，并继续补齐关于页、友链和移动端交互。', '["文章","友链","移动端"]', '["发布《朝朝听雨，岁岁有风》，补充文章封面、目录和阅读节奏。","新增 Wang Yijun Mew、Luming Notes 等友链。","修复故事文章在移动端的封面与目录布局，并让手机端樱花开关更可靠。","同步近期博客资料，为后续关于页和朋友圈展示准备真实内容。"]', '44,28,24,23,22,20', '2026-08-14 12:00:00', '2026-08-14 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (22, 'V1.8.1', '2026-08-15', 'minor', '友链体验', '让友链卡片开始展示站点本身', '友链从静态列表升级为带截图、预览和进场动效的可探索卡片。', '["友链","预览","动效","字体"]', '["新增友链站点预览图，并让预览层跟随对应卡片定位，不再漂移到页面其他位置。","连续调整预览进入、停留、退出和装饰裁剪，避免动画遮挡站点名称和操作区域。","将博客字体资源改为自托管，降低外部字体加载失败对排版的影响。","保留减少动态效果时的静态卡片和文字信息，保证预览不可用时仍可正常访问友链。"]', '48,40,31,24,21,20', '2026-08-15 12:00:00', '2026-08-15 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (23, 'V1.8.2', '2026-08-17', 'feature', '内容与管理', '补充个人内容，并建立评论管理入口', '继续完善博客内容和页脚体验，同时加入 AI 管理相关的安全验证代码。', '["文章","页脚","管理"]', '["发布青春主题随笔《我回望青春时，我的青春是最昂贵的；我正值青春时，我的青春是最廉价的》。","更新多篇项目文章的摘要、封面和文章元信息，使技术记录与个人叙事保持一致。","改善页脚内容和文章统计展示，减少长标题、长摘要在移动端的拥挤。","加入 AI 管理后台的安全邮箱验证流程；远端服务部署状态仍需在服务器侧单独确认。"]', '44,40,21,16,10,6', '2026-08-17 12:00:00', '2026-08-17 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (24, 'V1.8.3', '2026-08-18', 'feature', '友链与评论', '建立推荐友链和评论身份体系', '友链开始拥有推荐层级、真实截图和更完整的项目说明，评论区也更像站点的一部分。', '["友链","推荐","Waline","布局"]', '["新增林间随笔、陈义程博客、Sunrise 等友链，刷新多组站点名称、描述和项目截图。","增加推荐友链标记、推荐理由和降级状态，连接异常时仍保留可读的推荐信息。","调整推荐卡片动画、溢出布局和刷新行为，保证长标题和窄屏内容不会破坏页面。","优化 Waline 评论身份显示和编辑器空格保留，并完善页脚备案信息。"]', '36,31,30,25,22,21', '2026-08-18 12:00:00', '2026-08-18 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (25, 'V1.8.4', '2026-08-19', 'content', '友链维护', '补充友链资料与站点截图', '新增日和、星空驿站，并更新站点截图，让友链卡片更接近真实站点状态。', '["友链","截图","维护"]', '["新增日和与星空驿站友链。","刷新星空驿站截图，避免卡片继续展示过期页面。","同步站点近期资料和友链描述，为后续 RSS 聚合做准备。"]', '33,31,30,29,26,24', '2026-08-19 12:00:00', '2026-08-19 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (26, 'V1.8.5', '2026-08-20', 'content', '文章与友链', '继续写文章，也继续扩展连接', '发布性别关系主题文章，同时加入新的友链站点。', '["文章","友链","生活思考"]', '["发布《从母系社会到父权制度：亲缘、私有制与现代性别关系的演变》。","新增 Xe_iu 的杂物间与没吃饱的天镜镜等友链。","保留首页既有封面和内容入口，避免新文章发布影响首页视觉结构。"]', '44,40,31,30,29,25', '2026-08-20 12:00:00', '2026-08-20 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (27, 'V2.0.0', '2026-08-21', 'major', '朋友圈上线', '朋友圈正式接入友链 RSS', '博客从展示友链，进一步变成可以持续阅读友链更新的社区入口。', '["朋友圈","RSS","GitHub Actions","评论"]', '["新增朋友圈页面，从友链 RSS/Atom 聚合最近文章，并按时间线展示。","加入构建时快照、来源状态、失联回退和没有站点地址时的跳过逻辑，外部站点异常不会阻塞页面。","配置 GitHub Actions 定时刷新朋友圈快照，每天运行两次并自动部署更新结果。","新增分页、随机文章、闪烁粒子和状态提示，且在 Swup 切换后可以重新初始化。","同步完善 Waline 评论过滤；自动检测友链可用性的实验最终撤回，保留更可控的手动配置。"]', '71,29,28,10', '2026-08-21 12:00:00', '2026-08-21 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (28, 'V2.1.0', '2026-08-23', 'feature', '关于页与朋友圈', '把关于我改造成真正的个人主页', '关于页完成 GitHub 风格的信息重组，朋友圈补齐 RSS、分页和页面切换后的稳定性。', '["关于我","朋友圈","RSS","移动端"]', '["重做关于页的个人资料、README、项目、最近活动、技术轨迹和服务器状态区域。","新增更多友链 RSS 来源，朋友圈加入来源元数据和更完整的分页信息。","修复 Swup 页面切换后朋友圈粒子不重新初始化的问题。","优化手机端首页横幅、友链卡片和文章元信息，并更新站点头像与导航栏 Logo。","移除独立作品展示页入口，将项目介绍和设计思路收回到博客内容体系中。"]', '30,29,27,21,18,13', '2026-08-23 12:00:00', '2026-08-23 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (29, 'V2.1.1', '2026-08-24', 'minor', '社区与资源', '把友链、服务器状态和资源体积一起整理', '朋友圈和关于页继续补齐状态信息，同时完成站点图片资源的 WebP 迁移。', '["朋友圈","服务器","WebP","友链"]', '["新增 Evilrabbit、Nanzhi 友链，优化 Nanzhi 站点截图。","关于页、朋友圈和服务器状态接口同步更新，页面能更清楚地表达当前连接状态。","优化朋友圈随机文章切换，使随机阅读从加载到切换更自然。","将壁纸、头像、友链截图、音乐封面等大量资源迁移为 WebP，并保留必要的 PNG 回退。"]', '31,30,28,27,26,25', '2026-08-24 12:00:00', '2026-08-24 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (30, 'V2.2.0', '2026-08-25', 'minor', '友链漫游舱', '打磨友链漫游舱的进入体验', '围绕友链漫游舱的导航、启动、品牌提示和移动端回退完成连续优化。', '["友链","转场","移动端"]', '["新增友链漫游舱入口和专属导航，把普通友链卡片串成一条可探索的路径。","增加启动转场、品牌识别、终端式标题和 caption 保持状态。","重构启动转场的状态切换，调整文字对比度和动画时长，避免提示被背景吞掉。","手机端保留普通友链卡片，桌面端提供更完整的漫游体验。"]', '31,29,28,26,25,24', '2026-08-25 12:00:00', '2026-08-25 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (31, 'V2.3.0', '2026-08-26', 'feature', '友链漫游舱', '让友链漫游舱从概念变成完整入口', '完成友链漫游舱的材质、时间节奏、退出动画和后台辅助能力，并补齐部署流程。', '["友链","动画","后台","部署"]', '["新增 Moyor 与 SilverCode Nexus 友链，并恢复部分 PNG 头像和站点预览资源作为回退。","调整终端填充时机、表面纹理和退出动画，让长按跳转、关闭和返回之间的节奏更连贯。","统一导航栏自定义光标，修复不同页面之间光标样式不一致的问题。","加入手动小爱回复管理后台，并配置主分支推送后的自动部署流程。"]', '30,29,26,25,24,22', '2026-08-26 12:00:00', '2026-08-26 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (32, 'V3.0.0', '2026-08-28', 'major', '月刊与首页', '用月刊记录八月，也让首页更有空间感', '发布 8 月月刊，补充全屏首页装饰，并同步友链和依赖维护。', '["月刊","首页","装饰","依赖"]', '["发布《月刊》，集中记录本月的页面、评论、统计、友链、工作流和桌面环境变化。","首页增加全屏贴纸、角色装饰和壁纸联动，让不同壁纸拥有更完整的氛围层次。","月刊配套加入关于页、友链漫游舱、工具箱、统计面板等真实页面截图。","同步一轮 minor 与 patch 依赖更新，并继续补充友链资料。"]', '42,33,16,9,8,7', '2026-08-28 12:00:00', '2026-08-28 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (33, 'V3.0.1', '2026-09-04', 'minor', '依赖维护', '完成依赖兼容与安全维护', '集中更新项目依赖，保持 Astro、Svelte、构建工具和站点插件之间的兼容。', '["依赖","维护"]', '["同步 minor 级依赖更新，避免长期停留在旧版本造成构建和安全隐患。","同步 patch 级依赖更新，保持现有功能和页面行为不变。","依赖更新不改变博客内容和视觉结构，主要服务于后续构建稳定性。"]', '32,25', '2026-09-04 12:00:00', '2026-09-04 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (34, 'V3.0.2', '2026-09-06', 'minor', '收尾优化', '把博客收束成更稳定的日常入口', '完成首页、文章摘要、友链统计、页脚角色和壁纸切换的最后一轮细节收尾。', '["首页","友链","统计","视觉"]', '["优化文章摘要的打字呈现和结束状态，长摘要不会因为动画提前截断。","更新 Firefly 站点资料、友链页面内容和 RSS 入口，补充 Fourth World 友链。","合并历史友链点击统计，推荐友链徽章改为按内容自适应宽度。","更新页脚角色插画，并清理壁纸切换完成后的残留状态，减少返回页面时的视觉闪烁。"]', '43,42,39,38,37,35', '2026-09-06 12:00:00', '2026-09-06 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (35, 'V3.1.0', '2026-09-07', 'feature', '后台与导航', '让朋友圈跳转更稳，也把小爱后台补完整', '修正朋友圈页面切换路径，并完成小爱后台的收件箱、审计和人工回复辅助能力。', '["朋友圈","小爱","导航","友链"]', '["优化朋友圈页面跳转，进入文章详情时保持在内容区，导航不会被错误地带回其他位置。","完成小爱后台：增加运行状态、评论收件箱、筛选和分页，方便从后台查找需要处理的评论。","补充回复策略控制、快捷回复模板、草稿恢复和发布前预览，让人工回复更容易确认。","增加用量与审计记录，并使用博客头像作为小爱身份展示；同时新增“折腾进行中”友链。"]', '71,41,39,38,37,34', '2026-09-07 12:00:00', '2026-09-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (36, 'V3.1.1', '2026-09-08', 'feature', '评论区体验', '把评论区改成更直观的左右对话布局', '重做 Waline 评论展示，让访客留言与站长回复更像连续发生的对话。', '["评论区","Waline","交互"]', '["评论区更新为左右气泡布局，访客评论与站长回复拥有清晰的方向和层级。","补充评论区设备与浏览器图标，让评论元信息更容易识别。","保留 Waline 元数据并完善页面切换后的初始化，减少从其他内页进入评论区时的状态丢失。"]', '48,41,24,18,15,14', '2026-09-08 12:00:00', '2026-09-08 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (37, 'V3.2.0', '2026-09-09', 'feature', '友链与统计', '让友链卡片更有数据感，也新增公开统计页', '在友链页面补充延迟、点击和推荐信息，并上线独立的公开统计页。', '["友链","统计","玻璃卡片","数据"]', '["友链卡片新增站点响应延迟，让访问状态不再只停留在可用或不可用。","推荐友链增加左上角推荐标签，强化推荐关系和卡片识别。","新增玻璃质感的小卡片，展示友链点击次数与响应延迟。","重新整理友链卡片的玻璃材质、状态徽标和特殊状态视觉，并新增 UpXuu 友链。","新增公开统计页，集中展示访问趋势、热门页面、设备与浏览器分布，并接入导航入口。"]', '46,41,39,38,35,34', '2026-09-09 12:00:00', '2026-09-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (38, 'V3.2.1', '2026-09-10', 'minor', '统计页与友链', '让统计页在真实访问中更稳，也继续补充友链', '新增统计页的容错和加载优化，并补充星宇安全实验室友链。', '["统计","友链","容错","页面"]', '["新增星宇安全实验室友链，补齐站点简介、RSS、截图和网络安全、技术分享标签。","优化公开统计页的数据读取：加入请求超时、共享数据缓存和分模块请求，单个接口响应较慢时其他模块仍可显示。","补充统计页的部分在线、暂不可用和本地预览提示，并修复 Swup 页面切换后的初始化与清理。"]', '46,41,39,37,35,34', '2026-09-10 12:00:00', '2026-09-10 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (39, 'V3.3.0', '2026-09-11', 'feature', '统计页与交互动画', '把统计页做成一块会呼吸的真实数据面板', '重做统计页的数据模块与交互动画，接入访客地域、流量来源和 GitHub 推送历史，让公开统计更完整也更有反馈。', '["统计","动画","GitHub","Umami","导航"]', '["更新导航栏图标和导航配置，统一站点入口的识别体验。","重做统计页布局，新增访客地域分布、流量来源和基于 GitHub main 分支推送历史的热力图，并继续使用公开 Umami 数据驱动访问统计。","调整 Waline 评论区的懒加载触发和页面切换初始化，避免文章页评论区尚未进入可视区时未初始化，进而影响文章数据展示。","重塑统计页动画：为访客地域分布设计独立 SVG 动画，加入 GitHub 推送热力图贪吃蛇、启动缓入缓出和食物交互，并优化访问脉冲 7 天、30 天、90 天切换动画。","修复友链探测对 HTTP 错误状态的判断，让异常响应能正确显示为不可用。"]', '46,45,38,37,35,34', '2026-09-11 12:00:00', '2026-09-11 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (40, 'V3.4.0', '2026-09-14', 'feature', '内容与工具体验', '让文章、工具和动效都有更完整的入口', '补充白发主题随笔，加入文章影片与 Lottie 动效画廊，并重新整理工具卡片的推荐展示。', '["文章","工具","Lottie","动效","阅读体验"]', '["发布《在奶奶的白发里，我看见了时间》，记录陪伴家人、重新理解时间，以及开始创业的真实想法。","为文章加入沉浸式影片展示，把图片、镜头和文字组织成更连贯的阅读体验。","新增 Lottie 动效画廊和统一的动效资源索引，方便浏览、预览和复用表情动画。","重做工具页卡片结构，加入自动上架工具封面、推荐标识和星光流动效果，让项目入口更容易被识别。","继续优化文章目录、封面比例和页面切换后的交互状态，保证新内容在桌面端与移动端都能正常阅读。"]', '45,44,43,26,23,22', '2026-09-14 12:00:00', '2026-09-14 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (41, 'V3.5.0', '2026-09-15', 'feature', '评论区与友链', '让 AI 回复有迹可循，也让友链继续生长', '优化 Waline AI 回复体验，补充回复状态和管理能力，同时新增并整理一批友链。', '["评论区","AI 回复","友链","状态","后台"]', '["优化 Waline 评论线程的回复展示，区分普通回复、AI 回复与站长回复，长线程可以收起并按需展开。","为评论线程增加“AI 已回复”“站长已回复”等状态提示，让访客不用展开所有内容也能理解对话进度。","继续完善 Waline AI 回复后台，补充审核、回复策略、快捷模板、草稿和发布前预览等操作。","新增 UpXuu、星宇安全实验室、铭心の博客、冷月笙寒的小窝等友链，并补充头像、截图、RSS 与标签。","更新友链探测与延迟快照，调整部分友链状态和推荐标签，让异常站点有更明确的降级表现。"]', '46,45,38,37,36,35', '2026-09-15 12:00:00', '2026-09-15 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (42, 'V3.6.0', '2026-09-16', 'feature', '首页内容体验', '给月刊一个清晰的入口', '为 8 月月刊增加更醒目的封面角标，并替换导航栏手动播放器的视频内容。', '["首页","月刊","文章卡片","视频播放器"]', '["将原有播放器的视频替换为本地鸣潮混剪；视频仅在点击导航栏播放按钮后播放，不作为默认壁纸自动启动。","为《月刊》卡片增加浅薰衣草紫的“8月月刊”左上角角标，并移除底部标签栏中重复的月刊标签。"]', '43,34,32,16,9,8', '2026-09-16 12:00:00', '2026-09-16 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (43, 'V3.6.1', '2026-09-17', 'fix', '播放与公告修复', '收回自动视频壁纸，补齐工具更新公告', '将视频恢复为导航栏手动播放，并同步自动上架系统公告和文章版本信息。', '["首页","视频播放器","工具","公告"]', '["移除自动视频壁纸模式，保留导航栏手动播放器；图片轮播恢复为默认的首页壁纸体验。","同步自动上架系统最新公告，补充多店铺上架、目录识别、PNG 兼容和失败恢复等更新说明。","将自动上架系统文章的更新时间推进到 9 月 17 日，并为 Lottie 播放函数补充明确返回类型。","同步朋友圈和友链状态快照，保持日常社区数据的可追踪性。"]', '68,49,45,42,40,34', '2026-09-17 12:00:00', '2026-09-17 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (44, 'V3.6.2', '2026-09-18', 'content', '文章与内容维护', '把近期工程记录补进博客', '补充自动上架系统文章，并公开 Codex 状态分析文章，让最近的工程实践有完整内容入口。', '["文章","自动化","Codex","内容"]', '["扩展《自动上架系统》项目文章，补充从 v1.0.0 到当前版本的工程演进、运行边界和安全校验说明。","发布 Codex 状态分析文章，把近期对开发状态、工具链和工作流的观察整理成可持续阅读的内容。","完善新文章的封面和文章卡片展示，保证新增内容在首页与文章列表中拥有一致的入口。","同步朋友圈和友链状态快照，保持社区页面的内容与最近一次抓取结果一致。"]', '45,40,26,23,21,16', '2026-09-18 12:00:00', '2026-09-18 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (45, 'V3.7.0', '2026-09-21', 'feature', '统计与内容', '把统计、文章和工具入口一起推进', '将博客统计切换到自托管 Umami，同时发布 AI 电商 Agents 文章、更新自动上架工具版本并补充友链。', '["统计","Umami","文章","工具","友链"]', '["将博客统计切换到自托管 Umami，补齐迁移、导入、自定义域名和统计详情链接配置。","发布《AI 电商 Agents：从市场调研到主图生成的自动化工作流》，把近期的电商智能化实践整理成完整文章。","更新自动上架工具文章与工具入口，站点展示版本同步到 v4.1.1。","新增 Demius 友链并细化友链状态标签，让在线状态和异常状态更容易区分。"]', '46,44,43,41,40,39', '2026-09-21 12:00:00', '2026-09-21 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (46, 'V3.7.1', '2026-09-22', 'minor', '友链与导航维护', '把友链入口和导航顺序再理清', '新增 Chumendiao 友链，并调整 Travellings 入口顺序，让社区连接和主导航更容易理解。', '["友链","导航","社区","维护"]', '["新增 Chumendiao 友链，补齐站点截图和卡片资料，让新的社区连接拥有完整的展示入口。","将 Travellings 入口移动到“关于我”之后，重新整理外部入口在主导航中的阅读顺序。","同步朋友圈与友链延迟快照，让友链页面继续反映最近一次探测到的站点状态。"]', '51,45,41,39,38,37', '2026-09-22 12:00:00', '2026-09-22 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (47, 'V3.7.2', '2026-09-23', 'fix', '暗色模式修复', '让暗色模式下的文字重新清晰起来', '修复时间进度、评论数和今日一言等模块在暗色模式下文字过暗的问题，并检查多个页面的辅助文本对比度。', '["暗色模式","可读性","主题色","页面维护"]', '["为全局正文补上主题文字颜色，并补齐正文色与次级文字色变量，避免未设置颜色的内容退回浏览器默认黑色。","修复时间进度、评论数和今日一言在暗色模式下的文字显示，并复核“来自 xxx 的好友”等好友区文本。","调整日历、番剧、图库、赞助和海报分享等页面的提示、空状态与辅助文本颜色，提升暗色背景下的可读性。","同步站点信息卡片和页脚中的 Aemeath 版本号为 V3.7.2，与博客更新日志的当前版本保持一致。"]', '48', '2026-09-23 12:00:00', '2026-09-23 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (48, 'V3.8.0', '2026-09-26', 'feature', '导航交互升级', '让导航栏随滚动收放，外观设置更清楚', '重整桌面导航的模块布局和滚动交互，加入胶囊式收起与渐进展开，并把字体选择放进外观设置。', '["导航栏","交互","外观设置","字体","主题色"]', '["参考 Detached 的小模块导航形式，保留站点标识、主导航、搜索、播放器和主题控制，并让主导航继续居中。","调整滚动态的展开与收起：下滑后收成当前栏目胶囊，继续上滑或悬停时展开；鼠标离开后先收起二级菜单，导航栏再保持 5 秒后收回。","梳理顶部与滚动态之间的菜单定位和动画衔接，让活动栏目与其他导航模块沿同一过渡流程移动，并调整二级菜单的展开时机。","修正文章详情路径的导航选中状态；将字体切换移入外观设置，以“默认字体”和“霞鹜文楷”并排呈现，并统一字体与壁纸模式的主题色选中效果。"]', '56,49,47,36,22', '2026-09-26 12:00:00', '2026-09-26 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (49, 'V4.0.0', '2026-09-26', 'major', '站点体验重构', '把首页、内容页和侧栏重新接成一段流畅的浏览体验', '重构首页与内页的切换和页面布局，重做个人资料卡，新增公开账单页，并扩展可保存的外观设置。', '["页面切换","首页","侧栏","账单","外观设置","导航栏"]', '["首页进入其他页面时，先平滑滚动到内容区，再让中间内容入场；返回首页时让三列内容退场，经过白色过渡后呈现壁纸，减少切页时的突兀闪现。","让全屏壁纸只在首页展示，其他页面从导航栏下方直接展开；调整侧栏与中间内容的切页时序，避免两侧提前出现或重复播放入场动画。","重新设计侧栏个人资料卡，加入可切换的封面、独立头像、社交入口与访问统计，并统一卡片、首页标题和背景细节。","新增公开账单页，按年、月和日展示收支概览、趋势、日历、收入分类与支出排行；流水只展示分类、时间和金额，并注明统计口径。","在外观设置加入卡片装饰与导航栏滚动方式：可选择柔和蓝调或轻薄边框，也可选择随滚动收缩或始终展开的导航栏；偏好会保存在本地。","完善分类栏、移动端导航和樱花效果在页面切换后的初始化，减少交互状态丢失；把节日计算整理为共用逻辑，并优化时间进度展示。","继续调整友链页面、侧栏公告和导航细节，让新版页面在桌面与移动端保持一致的阅读节奏。"]', '68,66,60,56,48,43', '2026-09-26 12:00:00', '2026-09-26 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (50, 'V4.1.0', '2026-09-27', 'feature', '个人主页与站点记录', '给个人主页和博客历程补上清晰的入口', '重做“关于我”页面，补充开源项目、站点历程与服务器状态；更新日志新增时间线和关联图两种浏览方式。', '["关于我","开源","更新日志","友链","导航栏","账单","侧栏"]', '["将“关于我”页面整理为个人主页，加入项目展示、关注方向、技术轨迹、联系入口、服务器状态和站点里程碑，并适配桌面与手机布局。","补充开源项目说明，展示 Aemeath 源码仓库与 Firefly 主题来源，同时更新个人介绍和技术栈内容。","重做博客更新日志，支持在时间线与关联图之间切换；详情弹窗展示版本、标签和完整说明，也能继续查看共享主题的相关更新。","调整友链页的标签筛选和漫游入口，并细调侧栏个人资料卡、公告按钮与导航栏默认展开体验。","同步公开账单页的 9 月 27 日流水和新分类，并支持展示没有记录具体时间的流水条目。"]', '61,60,56,53,52,51', '2026-09-27 12:00:00', '2026-09-27 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (51, 'V4.1.1', '2026-09-28', 'feature', '月刊发布与站点体验', '发布第二期月刊，完善评论、友链与阅读体验', '发布九月月刊，补充文章专属的阅读设计；完善评论管理和友链申请，并优化组件加载与长文滚动表现。', '["九月月刊","评论区","Waline","友链","阅读体验","性能优化"]', '["发布《月刊·第二期》，回顾 8 月 27 日至 9 月 27 日的站点数据、文章、博客改版与友链故事；加入自建 Umami 的统计截图、文章封面和月刊专属封面。","为第二期月刊设计数据卡片、文章回顾、时间线和博友推荐等阅读模块，加入随阅读位置出现的轻量动画，并照顾减少动态效果的系统设置；首页卡片也能完整显示月刊封面与月份标识。","评论提交时检查昵称、内容与填写的网站地址，命中屏蔽词后给出明确提示；同时根据友链身份和普通访客身份应用不同的提交频率规则。","在 Waline 管理后台加入仅管理员可用的评论设置，可调整屏蔽词、统计时间、提交上限和提示语，保存后对新评论立即生效。","修正评论设置入口与弹窗交互，补齐默认值和关闭操作；评论表单会在填写网站地址后提示当前身份，登录用户也按其个人主页地址识别。","友链页新增申请入口，点击后进入评论区并预填申请格式；申请说明补充 RSS 地址，推荐友链也按最新名单整理。","让 Live2D 和友链漫游按需加载，减少首页初次加载的负担；长文章的滚动进度、返回顶部和导航显示减少重复更新，并修正切页后的状态同步。"]', '61,55,53,52,50,46', '2026-09-28 12:00:00', '2026-09-28 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (52, 'V4.1.2', '2026-09-29', 'feature', '国庆主题与站点优化', '加入可切换的国庆首页主题，完善移动端与评论管理', '加入可切换的中国红国庆主题，为桌面和手机分别配置节日壁纸、贴纸与首页卡片；区分两种模式的壁纸轮播默认值，并继续完善移动端和评论管理。', '["国庆主题","首页","移动端","壁纸","贴纸","评论区","Waline","友链","月刊"]', '["在外观设置加入“中国红-国庆专属”开关：开启后显示国庆配色、77 周年标识、云纹与飞鸽贴纸和节日首页卡片；关闭后恢复普通模式的壁纸、卡片尺寸与装饰。","国庆模式下桌面端只展示两张节日壁纸，手机端只展示一张专属竖屏壁纸；普通模式不展示国庆壁纸，并修复从其他页面返回首页时壁纸偶尔消失的问题。","壁纸轮播在国庆模式下默认关闭、普通模式下默认开启；两种模式分别保存用户选择，外观设置仍可手动切换。","修正旧壁纸选择与轮播偏好的迁移；桌面和手机分别选用对应的默认壁纸，普通模式不再加载国庆壁纸作为背景兜底。","调整国庆首页贴纸的相对位置，使其随界面尺寸变化；“盛世华诞 与你同庆”改用站点现有字体显示，保留“朝朝听雨”标题。","修正手机导航抽屉的层级和关闭状态，扩大菜单操作的触控区域；固定导航滚动后增加磨砂底色，改善菜单覆盖和阅读时的可见性。","将手机端文章悬浮操作收拢为横向短行，并适配屏幕安全区域，减少对正文的遮挡。","调整九月月刊文章推荐卡片的高度和网格布局，让卡片随内容伸缩，减少不必要的留白。","更新友链名单并同步站点生成的友链域名数据，新增“叁拾玖の小站”。","升级自建 Waline 服务端至 @waline/vercel 1.43.1；修复管理员登录后评论设置入口延迟显示的问题，登录状态变化后无需刷新即可显示。"]', '68,63,55,53,51,50', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (53, 'V4.1.3', '2026-09-30', 'feature', '壁纸、性能与评论体验', '更新国庆主题壁纸，优化首页加载与评论输入', '替换国庆首页桌面壁纸，并让壁纸和首页展示素材按页面按需加载；继续完善 Waline 评论输入与友链展示。', '["国庆主题","首页壁纸","性能优化","Waline","评论区","友链"]', '["将国庆主题桌面壁纸替换为新的烟花与红旗插画，转为 WebP 并更新缩略图和模糊占位数据。","首页壁纸和首页介绍素材只在首页预加载或按需载入；浏览文章、友链等内页时不再提前下载整张背景壁纸，返回首页后再加载。","友链头像改为延迟加载并异步解码，新增朽丘秋雨的站点截图，并刷新友链与朋友圈数据快照。","Waline 表情选择器新增颜文字分类，可将颜文字插入评论、回复或编辑框；调整手机端内联回复与编辑布局，并明确显示当前评论身份和操作状态。","修正登录评论者的头像解析：QQ 邮箱使用对应头像，其他邮箱使用 Libravatar。"]', '63,58,55,52,51,50', '2026-09-30 12:00:00', '2026-09-30 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (54, 'V4.1.4', '2026-10-05', 'feature', '友链、首页壁纸与界面样式', '新增 HJZ 友链，修复国庆壁纸随机选择', '新增 HJZ 的博客友链与站点截图，修复国庆模式随机壁纸加载后回退的问题；继续完善友链浏览、诊断工具和站点控件样式。', '["友链","WordPress","RSS","国庆主题","首页壁纸","动画","性能优化","界面样式","Waline","诊断工具"]', '["友链列表新增 HJZ 的博客，补充站点头像、RSS 地址和由站点内容整理的 WordPress、原创工具标签；首页截图转为 WebP 保存。","为友链头像流增加柔和阴影，并在悬停时轻微加深，让头像在浅色背景上更清晰。","修复国庆模式下首页桌面壁纸随机选中后，在页面初始化完成时被重置为固定第一张的问题；加载和恢复设置时保留当前随机选择。","友链页加入圆形头像流动条，悬停时暂停，点击头像可直达对应站点；保留两侧渐隐，并支持左右拖动和惯性滚动。","头像动画在页面离开视口或切换标签页时暂停，并适配减少动态效果设置；头像图片采用延迟加载和异步解码。","友链探测脚本支持指定站点诊断，输出响应耗时、HTTP 状态和失败原因；诊断模式不会修改友链状态快照。","新增可手动触发的 GitHub Actions 诊断工作流，并限制为只读仓库权限。","统一按钮、分页、筛选标签、评论操作和外观设置控件的透明底色与主题色边框；图库筛选同步标记当前选中状态。","调整手机端 Waline 评论关闭按钮的位置，避免遮挡其他操作。"]', '68,63,61,58,56,55', '2026-10-05 12:00:00', '2026-10-05 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (55, 'V4.1.5', '2026-10-06', 'feature', '评论体验与外观默认', '优化手机评论输入，同步访客外观默认', '手机端评论改用底部入口和弹出编辑面板，完善表情选择与悬浮控件布局；关闭中国红国庆主题的默认启用，并一次性同步所有访客的外观默认。', '["Waline","评论区","表情包","移动端","界面样式","外观设置","国庆主题"]', '["手机端进入评论区域时显示底部“欢迎评论”入口和表情快捷按钮；新评论、回复与编辑统一在底部弹出面板中完成。","评论编辑面板支持展开昵称与邮箱、取消编辑、点击遮罩或按 Escape 关闭；提交前提示补全必填身份信息，并根据手机键盘高度调整面板位置。","扩大手机端表情选择区域，增加展开与收起过渡，并适配深色模式和减少动态效果设置；可从底部表情按钮直接打开选择器。","将 BiliBili 表情包的 51 张图片与索引保存到站点本地，手机端优先展示该分类，打开这套表情无需再请求外部 CDN。","调整手机端评论正文、昵称和辅助信息字号，提高阅读清晰度；右侧悬浮操作恢复纵向排列，并上移为底部评论入口留出空间。","统一阅读进度按钮的透明底色、圆角和主题边框，移除底色阴影与模糊效果，让它与其他悬浮控件保持一致。","将“中国红-国庆专属”改为默认关闭，首页恢复普通模式的配色、壁纸与装饰；外观设置保留手动开启入口。","为所有访客加入一次性外观默认同步：下次打开或刷新页面时，清理旧的外观偏好，重新使用仓库当前配置；此前手动保存过的国庆主题选择也会一并恢复为关闭。","同步范围包括字体、明暗模式、色相、卡片装饰、导航栏滚动方式、壁纸及透明度设置、动画特效、文章列表布局和首页开屏设置。","同步在页面读取旧设置前完成，直接打开文章或其他内页时也会执行。","本次同步完成后记录状态，访客之后的新选择仍会正常保存；后续普通部署和主题版本更新不会再次重置，只有明确要求重新同步时才启用新一轮同步。","仅清理外观相关的旧偏好，保留评论资料、登录信息、音乐音量和统计缓存；浏览器限制存储访问时，同步脚本会跳过操作，避免中断页面初始化。"]', '57,56,54,53,52,51', '2026-10-06 12:00:00', '2026-10-06 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (56, 'V4.1.6', '2026-10-06', 'fix', '个人资料卡与导航栏样式', '优化复制提示并修复导航栏磨砂玻璃效果', '调整个人资料卡复制提示，修复生产构建丢失背景模糊样式的问题，让导航栏稳定显示半透明磨砂胶囊与独立菜单圆角底。', '["个人资料卡","导航栏","界面样式","剪贴板","无障碍"]', '["将微信和邮箱复制成功或失败的提示改为显示在对应图标上方的小浮层，沿用个人资料卡的配色和边框。","复制提示淡入后短暂显示再淡出，不参与卡片布局；验证复制前后个人资料卡高度保持一致。","保留无障碍状态播报，让屏幕阅读器也能读到复制结果。","修正导航栏背景模糊的兼容声明顺序，避免生产优化时只保留 WebKit 前缀、导致浏览器无法应用磨砂效果；品牌和菜单胶囊使用 24px 背景模糊。","恢复原有的半透明胶囊配色，保留主题边框与每个菜单项的圆角浅色底，让背后的文章文字模糊、壁纸色彩自然透出；同步修复搜索框、工具按钮及手机导航的模糊声明。"]', '61,55,54,50,49,48', '2026-10-06 12:00:00', '2026-10-06 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (57, 'V4.1.7', '2026-10-06', 'feature', '站点性能、字体与项目维护', '优化资源加载与中文字体，汇总站点检修和项目文档', '减少首页图片、脚本和中文字体的下载量，完善评论表情与统计页动画；汇总关于页、朋友圈及 Aemeath 项目文档调整，并同步到独立审阅分支。', '["性能优化","中文字体","Waline","统计页","移动端","Aemeath"]', '["将 Waline 评论运行逻辑拆分为独立模块，仅在页面包含评论区域时加载；评论样式随评论组件引入，并保留 Swup 页面切换后的初始化与清理。","搜索框和高级搜索共用按需加载的 Pagefind 模块，缓存同一次加载任务，避免在尚未使用搜索时提前请求索引。","首页桌面装饰图改为构建时压缩并限制尺寸，手机端不下载桌面装饰；本地生产构建中，装饰图文件合计从约 2.68 MiB 降至 524 KiB。","问候卡使用小尺寸壁纸缩略图并在进入视口时加载；首页开屏媒体在实际播放时选择对应设备资源，已经播放过的会话跳过媒体下载。","壁纸轮播在页面隐藏、离开首页或关闭壁纸模式时暂停，减少无效的计时器工作。","为霞鹜文楷新增构建期字体优化：共享首页常用字子集，按页面补充文字，保留未覆盖字符的原字体回退、字体切换及 OFL 许可信息。","在相同桌面视口的本地生产预览中，首页文楷字体下载量从约 943 KiB 降至 245 KiB，减少约 74%；同步验证手机端、长文章、页面切换和生僻字回退。这是字体传输量对比，不代表线上整页加载耗时。","放大手机端 Waline 静态和动态表情，常规手机使用六列、窄屏使用五列，并增加点击区域；桌面端保留原布局。","修复统计页热力图在首次加载和刷新后无法完整重播的问题，统一格子动画时钟，简化七天、三十天与自定义时间范围控件。","关于页资料卡底部改为透明背景；朋友圈卡片隔离绘制区域，移除悬停上浮，保留边框、底色和阴影反馈。","整理中英文 README、项目说明、贡献模板、配置与组件文档，统一 Aemeath 项目名称、仓库入口和文章工作台文案，同时保留原项目来源及版权说明。","性能分析脚本改为报告实际构建资源和 gzip 体积，补充字体优化文档；开源快照保留页面与功能入口，清理私有数据和部署连接配置，补齐月刊动画组件与账单装饰资源，修复空账单模板的月份类型，最新同步内容保留在独立审阅分支。"]', '75,66,65,59,58,55', '2026-10-06 12:00:00', '2026-10-06 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (58, 'V4.1.8', '2026-10-07', 'fix', '字体切页修复', '修复页面切换时文楷短暂回退的问题', '将按页面更换的字体样式改为全站稳定的共享样式，切页保留已加载的字体，并在进入新页面前准备所需字形。', '["中文字体","Swup","页面切换","性能优化"]', '["通过生产预览的过渡帧确认，旧字体 CSS 被移除时，已加载文楷会短暂清零；即使字体文件有缓存，仍会出现系统字体回退。","全站字体 CSS 使用统一的内容哈希 URL，保留字体样式节点并复用已经就绪的字形，避免导航栏、侧栏和文章在切页时因移除字体样式而回退。","首页常用字继续使用独立的小子集，其他页面文字按最多 128 个字生成共享分块，由 Unicode 范围按需加载；保留生僻字回退和字体许可信息。","文楷模式下，在替换页面内容之前加载目标文字所需的字体；默认字体模式跳过，等待超过两秒或加载失败时仍允许正常导航。","字体验证补充首次进入长文章、缓存往返及切页过程的字体就绪状态，避免只检查切页后的最终外观而遗漏闪变。"]', '66,65,59,57,54,53', '2026-10-07 12:00:00', '2026-10-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (59, 'V4.1.9', '2026-10-07', 'fix', '字体优化回退', '撤回文楷字体分包，恢复原有加载方式', '字体下载量的减少没有带来明显的浏览体验改善，切页却出现字体闪变和动画反馈问题，因此撤回这次字体优化，恢复原来的字体与页面切换流程。', '["中文字体","回退","页面切换","动画"]', '["移除 V4.1.7 新增的文楷构建期分包，重新直接使用原字体包提供的 Unicode 分片；保留默认字体与霞鹜文楷切换及访客已有偏好。","移除 V4.1.8 新增的切页字体预加载钩子，恢复优化前的 FontSetup 组件，不再额外等待目标页面字形加载。","保留原有首页进出、内容与两侧固定区域的页面切换动画代码，不再通过字体优化改变切页时序。","其他已完成的图片压缩、评论与搜索按需加载、壁纸轮播暂停和页面检修继续保留。","本次回退同步到个人博客主分支和 Aemeath 独立审阅分支，公开仓库保留原有配置与数据边界。"]', '66,65,62,61,58,57', '2026-10-07 12:00:00', '2026-10-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (60, 'V4.1.10', '2026-10-07', 'content', '账单汇总更新', '更新 10 月账单汇总', '账单页面汇总数据更新至 2026 年 10 月 6 日。', '["账单","数据更新"]', '["补充 2026 年 10 月 1 日至 6 日的账单汇总数据。"]', '50,49', '2026-10-07 12:00:00', '2026-10-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (61, 'V4.1.11', '2026-10-08', 'minor', '导航动画优化', '加快导航栏收缩与展开，减少菜单等待', '缩短导航栏随滚动收缩、悬停展开和二级菜单出现的等待时间，保留原有胶囊折叠效果，让导航操作更及时。', '["导航栏","动画","交互","阅读体验"]', '["将导航栏展开与收缩的主动画从 1.1 秒缩短至 0.32 秒，同步调整菜单宽度与模块位移过渡，保持折叠顺序和当前栏目的定位。","将菜单项显示的最大延迟从 0.76 秒缩短至 0.2 秒，并同步缩短胶囊背景、菜单淡入和箭头过渡，减少展开后继续等待的感觉。","将二级菜单的显现过渡从 0.26 秒缩短至 0.14 秒，仍在主导航展开后显示；鼠标离开后的 5 秒保持逻辑继续保留。","通过桌面与手机生产预览，验证快速反向滚动、键盘展开和移动端菜单；保留减少动态效果设置下的即时状态切换。"]', '62,59,56,54,51,50', '2026-10-08 12:00:00', '2026-10-08 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (62, 'V4.1.12', '2026-10-08', 'minor', '友链动效与推荐层级', '简化推荐友链扫光，调整推荐顺序与层级', '推荐友链沿用原有金黄色，改用单层斜向扫光，关闭卡片背景模糊和标题循环发光；重新整理主推荐与次级推荐的排序和动效。', '["友链","推荐排序","动画","性能优化"]', '["将多层光束、模糊光晕和背景位移动画替换为单层固定金色渐变，每 3 秒循环扫过卡片；动画只改变光带的 transform，不逐帧改变渐变背景或卡片布局。","扫光在卡片滚出屏幕、被搜索隐藏或页面进入后台时停止，重新可见后恢复；系统启用减少动态效果时不播放扫光。","保留 AIOVTUE-雪和 Detached 的流动星星，将 Detached 排在雪后面；夏夜流萤和 Homulilly 调整为次级推荐，保留黄色卡片与静态星星装饰。","恢复推荐友链名称原有的黄色，移除名字外面的圆角底框、边框与光晕，并关闭标题的循环发光。","移除友链卡片的背景模糊，简化推荐区域的持续动画层。"]', '78,67,64,63,61,59', '2026-10-08 12:00:00', '2026-10-08 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (63, 'V4.1.13', '2026-10-09', 'content', '友链更新', '新增阿珏酱のBlog友链', '新增阿珏酱のBlog，补齐站点简介、头像、标签和主页预览图。', '["友链","二次元","WebP"]', '["友链列表新增阿珏酱のBlog（moejue.cn），使用站点公开的名称、简介与头像。","根据站点内容补充二次元、技术分享、开源标签。","将提供的主页截图转换为 WebP，保留 1920×912 尺寸；文件体积从约 2.3 MB 缩减至 202 KB，并生成模糊占位图。","同步评论系统的友链域名列表，补充 moejue.cn。"]', '70,67,62,54,53,52', '2026-10-09 12:00:00', '2026-10-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (64, 'V4.1.14', '2026-10-13', 'feature', '双主题发布与性能优化', '上线 Pure 简洁主题，并减轻 Aemeath 首屏负担', '开放 Aemeath 与 Pure 双主题切换；按主题、页面和交互拆分运行代码，压缩首页壁纸并推迟轮播预取，减少首屏请求与持续动效开销。', '["Aemeath","Pure","主题切换","性能优化","壁纸","动效"]', '["上线 Pure 简洁主题，提供独立的页面呈现与主题切换；分别加载 Aemeath 和 Pure 的布局、导航逻辑，避免未选主题的运行脚本常驻。","将首页装饰、樱花、友链交互和壁纸轮播逻辑拆为独立模块，只有对应主题或页面需要时才加载；Pure 页面跳过 Aemeath 壁纸设置与运行逻辑。","首屏壁纸按访客选择和设备宽度设置预加载；轮播下一张等当前图片解码后延迟 1.5 秒，并在浏览器空闲时预取，避免与首屏资源同时争用带宽。","重新压缩 53 张 WebP 壁纸，文件总体积从约 45.7 MiB 降至 15.1 MiB，减少约 66.9%。","将 Sakura 动效默认关闭，同时保留设置中的手动开关；页面滚动时暂停 SVG 波浪动画，并降低评论身份标签扫光浓度，让光带两侧淡至白色。"]', '78,68,67,66,65,62', '2026-10-13 12:00:00', '2026-10-13 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (65, 'V4.1.15', '2026-10-13', 'minor', '页面切换体验优化', '为 Aemeath 页面切换补上轻量骨架加载', 'Aemeath 的 Swup 导航等待目标页面时按页面类型显示轻量骨架；快速完成的切换不闪屏，内容就绪或导航取消后立即清理。', '["Aemeath","骨架加载","页面切换","体验优化"]', '["首页与列表、文章、数据面板和普通页面分别使用匹配的骨架结构，并且只覆盖主内容区域。","导航开始 140 毫秒后才显示骨架，避免快速切换时出现多余闪烁；页面内容替换、导航取消、切页完成时都会隐藏并清除忙碌状态。","骨架只在 Aemeath 页面切换时启用，尊重减少动态效果设置；Pure 继续使用原有的目标路由骨架屏。"]', '71,66,64,59,58,57', '2026-10-13 12:00:00', '2026-10-13 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (66, 'V4.1.16', '2026-10-13', 'feature', '主题默认与页面切换体验', '默认使用 Aemeath，并恢复页面进退场动效', '将新访客的默认主题设为 Aemeath，移除本轮新增的 Aemeath 页面骨架，并恢复站内导航原有的进入与离开动画。', '["Aemeath","页面切换","进退场动画"]', '["没有保存主题偏好的新访客默认进入 Aemeath；访客主动选择的主题仍优先从本地记录恢复。","移除本轮新增的 Aemeath 整页骨架及其导航触发逻辑，恢复 Swup 页面原有的进场与退场过渡。"]', '65,64,59,58,57,49', '2026-10-13 12:00:00', '2026-10-13 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (67, 'V4.1.17', '2026-10-15', 'minor', '友链交互与标签配色', '完善推荐友链文字扫光、头像呼吸与标签配色', '为 Aemeath 主推荐友链增加同步文字扫光和头像呼吸，悬停时保留放大并暂停呼吸；标签文字按各自头像主色显示。', '["友链","动画","交互","头像取色","Pure"]', '["AIOVTUE-雪和 Detached 的名字及“推荐友链”文字增加白色扫光，与卡片共用 3 秒周期和启停状态；调整光带宽度与亮度，并去掉模糊光晕，保留字形的清晰度。","主推荐头像整体以 3.6 秒周期轻微缩放；悬停或键盘聚焦时只暂停头像呼吸，保留原有的 1.05 倍放大，扫光与星星继续播放，移开后恢复呼吸。","次级推荐继续保留静态卡片装饰，不增加文字扫光或头像呼吸；系统启用减少动态效果时，主推荐的文字扫光和头像呼吸也会关闭。","友链、本站及加入项目的标签文字复用 Pure 主题的头像取色规则，分别适配明暗模式；没有可用取色数据时使用中性灰，保留原有标签边框和背景。"]', '72,70,68,64,63,62', '2026-10-15 12:00:00', '2026-10-15 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (68, 'V4.1.18', '2026-10-19', 'minor', '备案信息与首页页脚维护', '补齐备案信息，更新地月动画并精简首页卡片', '在双主题页脚展示正式备案与萌备案，修复 RSS 图标和图文对齐；以真实地球、月球贴图重做运行时间动效，并移除首页公告、恢复欢迎便签位置。', '["备案","页脚","地月动画","RSS","首页","Pure"]', '["Aemeath 与 Pure 页脚底部展示粤ICP备2026158473号，使用工信部备案系统的网站图标并链接到备案查询系统；萌ICP备20260788号排列在正式备案之后。","补齐双主题页脚 RSS 图标，统一备案、RSS 等链接的图标尺寸与垂直对齐，让整组备案信息居中显示。","将 Aemeath 运行时间旁的时钟替换为地球与月球场景：使用真实地表、云层与月面贴图进行球面投影，地球缓慢自转，月球沿倾斜轨道环绕，并呈现前后遮挡与远近大小变化。","地月场景使用原生 Canvas 渲染，纹理在进入视口后加载；滚出屏幕或页面进入后台时暂停，系统开启减少动态效果时静止显示，并在脚本或纹理不可用时保留静态预览。","收紧地球与运行时间文字之间的空白，胶囊宽度随内容调整；移除首页主卡片里的站点公告及其样式，恢复“欢迎访问”便签的原始位置，让主卡片随内容收短。","从“加入的项目”中移除八零圈，并清理对应的头像取色缓存。"]', '67,64,54,52,49,43', '2026-10-19 12:00:00', '2026-10-19 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (69, 'V4.1.19', '2026-10-22', 'fix', '运行环境安全更新与迁移', '更新网站运行环境，完成历史服务版本迁移', '更新 PHP、Node.js 与证书信任库，迁移 Nginx、Docker、MySQL 和面板 Python；保留评论、访问统计及现有配置，并完成线上接口与数据完整性核对。', '["安全更新","部署维护","PHP","Node.js","Nginx","数据库"]', '["PHP 从 8.2.28 更新至 8.2.35；评论服务的 Node.js 从 24.18.0 更新至 24.22.1，访问统计服务从 22.23.2 更新至 22.23.4，两个 Node.js 运行时的内置 OpenSSL 同步更新至 3.5.9。","更新系统及应用使用的证书信任库，移除本轮已撤信的根证书；系统 OpenSSL 更新至 3.0.22，并核对面板 Python、certifi 和 pip 内置证书库的实际信任状态。","Nginx 从 1.26.3 迁移至 1.30.6，将独立构建中的 OpenSSL 从 1.1.1q 更新至 3.5.9；保留 Lua、HTTP/3、缓存清理等原有模块能力，补齐开机启动和面板启停入口。","Docker 从 20.10.24 更新至 29.9.2，配套更新 containerd、runc 和内置 Go 运行时；逐项核对容器镜像、环境配置、启动命令、端口与数据挂载，恢复评论审核服务。","核对 MySQL 实际用途后，从 5.7.44 迁移至 8.4.13 LTS，使用独立数据目录完成验证后切换；评论与访问统计继续使用原有 SQLite、PostgreSQL 数据库。","宝塔面板从 10.0.2 更新至 13.1.0，面板 Python 从 3.7.16 迁移至 3.13.17，更新 pip、certifi 与加密依赖；保留原有账号、安全入口、证书和关键配置，并验证重启后的登录页面。","核对维护前后的 468 条评论与 SQLite 完整性，验证网站首页、友链、统计页、评论读取、统计心跳和服务器状态接口；保留旧环境及受限回退备份。"]', '', '2026-10-22 12:00:00', '2026-10-22 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (70, 'V4.1.20', '2026-10-22', 'feature', '评论 AI 情绪与意图识别', '为评论补充情绪与意图标签，接入小爱后台筛选', '在评论头部展示 AI 识别的情绪和交流意图，支持一条评论对应多个标签，并在小爱后台按友链申请、问题反馈等分类查找留言。', '["评论","小爱","AI","情绪识别","意图识别","友链"]', '["情绪覆盖正向、感谢、期待、友好、好奇、困惑、吐槽、失望、担忧与难过；意图覆盖想交换友链、更新友链、提问求助、反馈问题、提出建议、交流讨论、来访问候、表达感谢、分享资源与商务合作。","标签排列在评论头部回复状态之后，适配手机换行和明暗主题；同一条评论可同时显示多个情绪与意图，并注明 AI 识别仅供参考。","小爱后台收件箱同步展示分类，新增情绪与意图筛选，方便查找友链申请和问题反馈。","后台异步识别已审核评论并缓存结果，不阻塞评论提交；普通陈述或判断不明确时不强行贴标签，评论编辑后重新识别，未审核及已删除内容不公开标签。"]', '75,74,72,71,67,63', '2026-10-22 12:00:00', '2026-10-22 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (71, 'V4.1.21', '2026-10-22', 'feature', '小爱后台与评论体验优化', '小爱收件箱改为紧凑表格，补齐逐条回复与自由标签', '将评论管理整理为小爱后台的独立页面，集中展示审核、回复、情绪和意图，补齐搜索、翻页、草稿与逐条回复操作；情绪和意图由 AI 自由概括，并精简前台标签展示。', '["评论","小爱","AI","后台管理","体验优化"]', '["情绪与意图标签由大模型根据评论自由概括，不再限定固定类别；同一条评论可保留多个标签，每个情绪标签最多 4 个字符、每个意图标签最多 8 个字符，并兼容读取旧分类、按内容重新识别。","评论收件箱与“运行与设置”分为独立页面，可在小爱后台顶部切换；全宽紧凑表格并排展示访客、评论摘要、情绪、意图、审核和小爱回复状态，每页显示 25 条，长评论可展开全文。","默认隐藏小爱已回复的评论，可切换“已回复”或“全部评论”查看；支持昵称、正文、页面和 #评论编号搜索，结合审核状态、情绪与意图筛选，并可一键清空条件。","桌面滚动时固定筛选栏和列标题，页面顶部与底部均提供翻页入口；翻页及发布回复后保留筛选条件，减少处理多条留言时的重复操作。","每条评论下直接展开已有对话和回复区，自动绑定当前评论，无需填写或选择 ID；可手动回复、生成 AI 草稿或润色，保留表情、快捷模板与最终公开内容预览，草稿确认后再发布。","草稿按评论分别保存，未发布时显示“继续回复”；展开编辑区自动定位输入框，支持 Esc 收起。识别已完成但某一类别没有明确标签时显示“—”，与等待识别区分。","精简前台评论头部的附加信息，移除情绪与意图标签前单独的“AI”字样，保留悬停时的 AI 识别说明，并兼容旧标签与新生成标签。"]', '75,70,65,35,27,3', '2026-10-22 12:00:00', '2026-10-22 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (72, 'V4.2.0', '2026-10-24', 'feature', '友链长廊、卡片与页面动效优化', '改进友链长廊预览与性能，默认开启主页樱花', '友链头像长廊改用 CSS 自动向右流动，悬停时暂停并保留站点跳转；主页预览改为按需加载并提供骨架动画，同时补充友链响应时间与离屏动画暂停。', '["友链","性能优化","按需加载","动画","樱花"]', '["头像长廊由逐帧脚本驱动改为 CSS 匀速动画，默认向右移动；鼠标悬停或键盘聚焦时暂停，离开视口或切到后台时停止播放，减少持续运行的脚本工作。移除鼠标拖动，头像点击仍会打开对应站点；系统启用减少动态效果时改为静止列表。","站点主页截图只在鼠标悬停或键盘聚焦对应头像时加载；缺少截图时显示 no-photo 图片，加载过程中使用轻微流动的骨架占位，图片加载失败后回退到默认图。","友链卡片新增 HTTP 响应时间。部署工作流从探测节点发起 GET 请求，在收到响应头后结束计时，不下载完整页面；悬停说明会注明探测节点和时间，超时或 HTTP 错误只展示探测结果，不改变友链可见状态。","卡片访问指标以紧凑数字展示；本站卡片显示总访问量，其他友链显示从本站产生的点击次数。","推荐卡片的星星形状和光晕绘制为可复用缓存，并在滚出屏幕、页面切到后台或减少动态效果时暂停动画。","樱花特效只在主页运行并默认开启；一次性偏好迁移会更新已有访客的旧关闭设置，迁移后仍可自行关闭。进入其他页面或站内切页离开主页时，樱花动画会停止。"]', '78,77,76,74,70,67', '2026-10-24 12:00:00', '2026-10-24 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (73, 'V4.2.1', '2026-10-24', 'fix', '小爱头像与站点图标更新', '统一小爱头像，更新评论与友链默认头像', '将新头像转为 WebP 并用于导航栏、小爱评论和友链头像加载失败回退；同步更新浏览器站点图标，保留评论区访客默认猪头头像。', '["小爱","头像","WebP","评论区","友链"]', '["使用新提供的形象生成 512 × 512 WebP 主图，并生成浏览器图标需要的 PNG 尺寸；更新导航栏品牌头像与浏览器站点图标。","Waline 评论区和站点统计中的小爱发言统一使用新头像；友链头像加载失败时使用新默认图。评论区普通访客无头像时仍显示原有猪头头像。"]', '79,78,77,76,75,74', '2026-10-24 12:00:00', '2026-10-24 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (74, 'V4.3.0', '2026-10-27', 'feature', 'AIGC 子站与友链扩展', '上线独立 AIGC 无限画布，并新增两条友链', '将无限画布部署为独立的 aigc.rainzt.cn 子站，使用单独仓库和自动发布流程；友链页新增 Muyu の 小窝与 Alexander。', '["AIGC","无限画布","独立子站","自动部署","友链"]', '["上线 AIGC 无限画布独立子站（aigc.rainzt.cn），构建为静态网页并部署到独立站点目录，由独立域名和 Nginx 站点配置提供访问，不与博客的 dist 文件互相覆盖。","画布项目使用独立的 GitHub 私有仓库和 main 分支自动部署；提交后自动检查与构建，构建失败时保留当前线上版本，博客与画布分别发布。","画布本身不在站点服务器运行生成模型；访客在浏览器中管理画布和素材，并使用自己配置的 AI 服务。导入图片默认保存在访客自己的浏览器，需要调用模型时才发送给所选 AI 接口。","友链页新增 Muyu の 小窝和 Alexander，补齐站点简介、头像、RSS 与主页截图信息。"]', '79,77,76,73,72,70', '2026-10-27 12:00:00', '2026-10-27 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (75, 'V4.3.0', '2026-10-28', 'feature', 'AI 评论审核与小爱后台升级', '加入发布前 AI 审核，统一小爱后台与评论提交反馈', '评论发布前分别检查昵称、正文与网站链接，违规时说明具体原因；小爱后台统一为无限画布风格，新增审核测试页，并用毛玻璃遮罩展示审核与发布状态。', '["评论","小爱","AI 审核","昵称审核","后台管理","移动端"]', '["新评论和楼中楼回复在保存前进行 AI 审核，昵称、正文与网站链接分别检查，每项规则取三个字段中的最高违规概率，避免正常正文抵消违规昵称。未通过的内容不入库，访客可以保留原文并返回修改。","小爱后台新增评论审核设置，可选择辱骂与骚扰、仇恨与歧视、色情内容、暴力威胁、隐私泄露、垃圾广告与诈骗等规则，调整拦截阈值与请求超时。默认使用硅基流动的 OpenAI 兼容接口，同时适配 Jev 原生 System One 协议；两种协议分别保存接口、模型与密钥。","新增独立审核测试页，支持填写昵称、正文与网站，也可只测试昵称；展示审核结论、各项概率、耗时和访客看到的提示。示例按钮只填入内容，执行测试后才调用已保存的接口，测试不会发布评论。","登录、评论收件箱、运行与设置、评论审核和审核测试统一采用无限画布的点阵背景、胶囊导航与轻边框样式，补齐窄屏布局；文楷字体改为小爱服务同源提供，避免外部字体加载失败或博客静态目录替换后字体丢失。","评论提交改用编辑框内的毛玻璃遮罩：等待时显示“AI 审核中”，未通过时直接展示违规类别、原因和“返回修改”，通过后过渡为“正在发布中”，替换原生浏览器弹窗。","遮罩高度随内容调整，修复电脑和手机上按钮超出底边的问题；手机长原因可在遮罩内滚动，保留底部安全区和触控区域，发布过渡显示后再关闭评论面板。返回修改保留草稿，并兼容明暗主题和减少动态效果设置。","补充辱骂规则中的亲属攻击、死亡诅咒与谐音绕写判断边界，区分正常批评、哀悼和劝阻式转述；继续使用接口原始概率和后台保存的阈值，不强改评分。接口异常与内容违规分别提示，审核服务不可用时拒绝本次提交并提示稍后重试；邮箱、IP 和浏览器信息不发送给审核模型。"]', '79,77,73,71,70,57', '2026-10-28 12:00:00', '2026-10-28 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (76, 'V4.3.0', '2026-10-29', 'content', '第三期月刊与推荐友链更新', '发布第三期月刊，完善月度推荐友链', '发布 10 月月刊并整理月度推荐友链；在评论区加入快速申请入口，修复申请按钮在评论区延迟加载时停滞的问题。', '["月刊","友链","推荐","快捷申请","评论区","欢迎提示"]', '["发布《月刊 · 第三期》，回顾本月文章并介绍 Muyu の 小窝、RAGNote 和阿珏酱のBlog；月刊沿用滚动入场和友链卡片展示，兼顾减少动态效果的设置。","推荐友链按 8 月、9 月和 10 月分组，卡片显示对应月份，补充各站的推荐理由；10 月三位友链使用次级推荐样式，评选说明中的月刊链接更新至第三期。","新增花园电波友链。评论区提供快速申请友链按钮，点击后滚动到评论区并填入申请模板；入口会等待延迟加载的 Waline 编辑器，失败时给出可重试提示，不再因评论区尚未初始化而无响应。","调整欢迎提示的头像、边框和背景，使其更贴合博客风格，同时保留关闭操作与键盘焦点提示。"]', '79,78,77,74,73,72', '2026-10-29 12:00:00', '2026-10-29 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (77, 'V4.3.0', '2026-10-30', 'feature', '小爱友链管理与发布流程升级', '在小爱后台管理友链，并完善申请审核与发布记录', '小爱后台可以查看、审核和维护友链资料，站长确认后通过 GitHub 更新网站配置；补充回链状态筛选、重审与拒绝操作，并发布配有完整截图的小爱后台介绍。', '["友链","小爱后台","GitHub 发布","AI 审核","回链检查","部署优化","文章"]', '["友链正式资料以博客仓库中的配置为准。后台使用 GitHub 内容接口读取和提交单条友链更新，校验文件版本并保留其余资料，避免并发修改覆盖新内容；提交结果与网站实际部署状态分别核对。","友链申请详情展示原始留言、AI 分析、回链证据、申请时间和站长处理状态；站长可以校对资料、同意添加、拒绝申请或要求重新识别。AI 建议不替代站长决定，AI 未通过也不阻止站长手动确认。","申请列表新增待处理、已拒绝和全部申请筛选，优化状态标记、推荐开关与处理中的按钮反馈；后端核验申请版本和原始留言，避免对已经变化或已处理的申请执行过期操作。","回链检查可按友链状态筛选，并把找到、未找到和暂时无法确认分开记录；定时与手动扫描只提供证据，不会自动修改友链配置或下线网站。","保留已收集申请的 AI 审核结果，修正已发布状态的过期显示；追加新友链时保留现有顺序，并将昭鸢笺加入友链列表。","改进静态站点发布流程，只传输变化文件并验证归档结果，减少每次发布的重复上传；补充发布状态核对和失败时保留当前线上版本的保护。","发布《小爱后台》功能介绍文章，新增并排与纵向截图画廊组件，展示评论收件箱、AI 回复、友链审核、回链检查和后台登录等实际页面。"]', '79,76,75,74,73,72', '2026-10-30 12:00:00', '2026-10-30 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (78, 'V4.3.1', '2026-10-31', 'feature', '评论互动与网站安全维护', '完善评论互动、图片体验与源站防护', '减轻评论输入与表情加载开销，补齐邮件回复定位和匿名点赞归属校验；同时启用 CDN 回源请求校验与邮件域名防冒用策略。', '["评论区","点赞安全","邮件通知","源站防护","DMARC","图片上传","性能优化"]', '["动态表情选择器按超级表情和小黄脸表情分组，以轻量静态预览代替一开始就加载所有动画；悬停或键盘聚焦时才播放，离开后释放播放器。评论输入同步减少重复初始化和高频重绘，降低长评论输入时的卡顿。","评论区支持图片上传。JPG、PNG 和 WebP 在浏览器中压缩为 WebP，GIF 保留动画；图片草稿暂存于浏览器本地，编辑框使用短图片标记，提交时再还原为图片数据。","编辑区保留普通 Markdown 原文，图片标记以内联节点显示为蓝色波浪下划线；悬停可预览图片，点击或键盘操作可查看大图，退格或删除键一次移除完整标记。","评论正文限制为 1,000 字，统计时排除图片数据，避免图片 Base64 内容占满评论长度限制。","修复邮件中的“查看完整对话”链接在回复被折叠或评论位于后续分页时无法定位的问题：自动翻到目标评论、展开回复并定位高亮。","匿名点赞由服务端按访客 IP 和评论记录归属；同一 IP 对同一评论只能点赞一次，取消操作只能撤回自己的一赞。升级后保留既有点赞数字，不尝试猜测旧点赞的归属。","为博客、AIGC 子站、API 和统计域名启用 Nginx CDN 回源请求头校验；经 CDN 访问保持正常，直接访问源站内容返回 403。此处采用回源凭据校验，不是源站防火墙的 CDN IP 段白名单；证书 ACME 验证路径保留，PHP-FPM 状态页不再对公网开放。","为 rainzt.cn 发布 DMARC 拒收策略，覆盖主域与子域并要求 SPF、DKIM 严格对齐；公网 DNS 查询已确认记录生效，收件方可据此拒收认证失败的冒名邮件。","微调评论身份标签的垂直留白；修复友链推荐卡片误隐藏推荐图标的问题。"]', '79,76,73,72,64,62', '2026-10-31 12:00:00', '2026-10-31 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (79, 'V4.3.2', '2026-11-01', 'feature', '友链审核自动化与管理体验优化', '友链申请按小时扫描，完善批量提交与站长回复', '友链申请每小时自动扫描，补齐评分扣分项、待提交改动和可选的管理员通知；发布记录默认收起明细，统一操作样式，并修复评论图片的大图查看。', '["友链","小爱后台","AI 审核","GitHub 发布","评论区","图片查看","体验优化"]', '["后台每小时自动扫描友链申请，保留手动立即扫描入口，不再需要每次打开后台触发；扫描只更新审核资料与建议，不代替站长同意添加。","友链评分调整为缺少 RSS 扣 10 分、缺少主页图扣 20 分；使用默认缺图占位图也按缺少主页图处理，审核说明会列出对应扣分项。","修复点击“我同意添加”后没有变化、也没有待提交改动的问题。新增、修改、删除和排序统一暂存在当前友链审核页，核对后批量提交到 GitHub；支持逐项撤销或放弃全部改动。","新增申请在 GitHub 提交成功后，可选以真实 Waline 管理员身份回复原留言，按申请人昵称生成称呼，并提供友链页面与构建等待说明；手动新增和普通资料修改不会触发这条通知。拒绝申请时也可发送站长拒绝通知，或取消勾选只执行拒绝。","新增当前 Waline 管理员登录的连接入口。站长明确授权后，服务端验证管理员身份并安全保存凭据，不保存密码、不签发新 token，也不将凭据写入仓库或日志。未连接或身份验证失败时明确提示回复未完成，不影响友链提交结果，连接后不自动补发历史漏发评论。","发布记录保留每批次的友链与字段前后对比，区分提交结果与网站实际上线状态；改动明细默认收起，手动展开的记录在刷新状态时保持展开，查看提交与工作流的入口统一为轻量文字和细线图标。","修复评论附件图片无法点击放大的问题，接入图片查看器；同一条评论的多张图片可连续查看，不把不同访客的图片混在同一组，评论翻页和展开回复后也无需重新绑定。表情图片保持原有交互。"]', '78,77,76,75,74,73', '2026-11-01 12:00:00', '2026-11-01 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (80, 'V4.4.0', '2026-11-06', 'feature', '听雨茶室与社区互动升级', '新增听雨茶室，完善群公告、聊天互动与站长管理', '新增原生聊天室，支持访客落座、Waline 账号、表情图片、提及和拍一拍；补齐群公告、资料与记录管理、AI 文字审核及数据维护，并调整主题切换和导航入口。', '["听雨茶室","聊天室","群公告","表情与图片","AI 审核","小爱后台","主题切换","移动端","部署优化"]', '["新增“听雨茶室”页面，使用原生 Svelte 界面与独立聊天服务。访客填写昵称和邮箱即可进入，网站为选填项；也可使用现有 Waline 账号登录或注册。账号用于验证身份，茶室资料、聊天记录和图片独立保存，不混入评论数据。","聊天支持实时收发、历史分页、断线重连与引用回复，同一条消息超时重试不会重复保存。邮箱不在公开消息或名单中展示；未上传自定义头像时，QQ 邮箱使用 QQ 头像，其余邮箱沿用评论区的头像回退方式。","表情复用 Waline 的精选、QQ 动态、Bilibili、微博、Bmoji 和本地颜文字资源。动态表情在可见时播放，并尊重系统减少动画设置。图片支持选择、粘贴和拖入，按输入顺序与文字分条发送，每张图片独立成一条消息；上传前压缩为 WebP，发送失败时保留尚未确认的内容和排列顺序。","图片按聊天身份限制为 10 分钟内最多成功发送 5 张，从第一张成功发送开始计时，后续发送不延长窗口。上传失败和同一消息重试不占次数，删除消息不退还次数；刷新、重连或服务重启不会重置额度，文字仍可正常发送。","茶室使用自定义头像右键菜单，可直接 @ 对方或拍一拍。拍一拍显示双方昵称并带轻微头像反馈，每个身份从第一次成功操作起的 1 分钟内最多 3 次；超限提示显示 5 秒，并在显示期间更新剩余等待秒数。","@ 提及支持昵称搜索和同名身份选择。配置邮件后，由服务端向经过校验的被提及者发送提醒，发送失败会重试，并限制通知频率；浏览器不会获得收件邮箱或 SMTP 凭据。","点击头像或昵称可在原页面打开茶友资料，查看个人网站、简介、身份标签和发言统计；本人可修改昵称、网站、简介及头像，上传头像会裁切并压缩为 WebP。推荐友链按网站域名匹配，站长与推荐友链使用统一的头像圈和昵称配色。","新增茶友名册，支持全部茶友、当前在线、昵称搜索及分页，显示在线状态和历史最后发言时间。站长在侧栏和名册中置顶，离线时保留座位并明确标记，在线人数只计算实际连接的身份；同一身份的多个标签页合并计数，发言统计覆盖全部保留记录，不只统计最近一页。","新增茶室设置，站长可管理游客发言、全员禁言、发送间隔与图片大小；茶友管理支持身份标签和删除用户，记录管理支持搜索、类型筛选、批量删除及清理已删除占位。删除和禁言均由服务端核验权限，删除用户会同步清理相关资料、会话、聊天记录与上传图片。","侧栏新增“群公告”卡片，站长可在“茶室设置 → 群公告”直接编辑、预览、保存和控制显示，支持最多 1000 字及换行分段。公告保存到数据库并同步给在线茶友，关闭显示仍保留内容，留空时隐藏卡片。","首次进入茶室会弹出当前群公告，按钮显示 3、2、1 秒阅读倒计时，结束后才可点击“我已知晓”；阅读前无法通过 Escape 或点击遮罩跳过。确认记录保存在当前浏览器，再次进入不重复弹出，公告内容更新后重新提醒。","茶室可接入小爱的 AI 文字审核，在消息保存、广播和提及邮件入队前检查昵称与正文。茶室和评论区使用独立开关，共用模型、规则、阈值与密钥；图片不参与文字审核，邮箱、IP 和会话凭据不发送给模型。输入区显示审核进度，未通过时说明原因并提供“返回修改”，保留未发送内容。","新增过期未发送图片清理、手动和自动备份、备份下载及禁言管理。数据库和图片需要一起备份；补充独立服务的 Docker、Nginx、SMTP 与审核桥接配置示例，运行数据及私有配置排除在仓库之外。","茶室采用固定一屏布局，收起博客两侧栏、页脚和悬浮控件，聊天记录在面板内滚动。玻璃输入框与消息头像边缘对齐，随文字自动展开，最高不超过聊天区域的三分之一；移动端通过人数按钮展开侧栏，点击空白处可关闭。","收紧“茶室小约定”的多余留白，统一卡片、弹窗和半透明胶囊按钮的圆角与触碰反馈，优化昵称、刷新按钮、表情及图片入口。新增茶室横幅、睡眠小插画、确认弹窗小猫及公告爱心信封插画，页面资源使用压缩后的 WebP。","将“听雨茶室”放到主导航的友链与朋友圈之间，留言板和开往移入“关于”菜单。Aemeath 与 Pure 主题切换移至外观设置最上方，统一切换逻辑并释放旧布局的组件与效果；茶室页面切换使用完整加载，避免残留博客侧栏。","小爱后台分别展示评论和茶室审核的接入状态。同步补齐部署工作流中的审核页面、脚本与样式文件，并追加发布版本标识，便于核对当前服务资源；新增聊天及审核联动的自动化测试。","按当前友链配置同步头像主色缓存、Waline 友链域名清单及茶室推荐名单，保持身份展示与现有友链资料一致。"]', '86,85,84,83,82,81', '2026-11-06 12:00:00', '2026-11-06 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (81, 'V4.4.1', '2026-11-07', 'feature', '茶室聊天体验完善', '茶室支持消息撤回、阅读进度、搜索与小猫回应', '补齐消息撤回、未读与提及定位、历史搜索、六款小猫回应和本地草稿恢复，发送失败可保留原消息安全重试。', '["听雨茶室","消息撤回","阅读进度","聊天搜索","小猫回应","草稿恢复"]', '["自己发送的文字和图片在 2 分钟内可以撤回，电脑右键、手机长按消息打开操作菜单；撤回后保留提示，原图片链接失效，尚未发送的提及邮件取消。服务端核验作者和时限，图片发送额度不退还。","阅读位置随茶室身份保存，再次进入回到未读消息附近，并显示“上次看到这里”、未读条数和未读 @ 定位。多标签页和设备共用进度，页面后台与弹窗遮挡时不会自动计为已读。","所有茶友可以按关键词、昵称和北京时间日期范围搜索聊天记录，点击结果回到原消息并高亮，可继续往前或往后翻阅，也可直接回到最新。","新增喜欢、点赞、喝茶、抱抱、开心、晚安六款透明底小猫回应插画，菜单采用两排圆角卡片，消息下方显示图案和人数，点击可以加入或取消。回应实时同步并保存，重复请求不会多计。","Waline 评论区与听雨茶室同步新增“尤诺宝宝”表情分组，包含打招呼、比心、开心、抱抱、委屈、气鼓鼓、震惊、疑惑、害羞、困困、点赞、喝茶，并追加生成收到、谢谢、加油、贴贴、吃瓜、晚安，共 18 张透明 WebP 表情；两边共用同一份本地素材与清单。","尤诺宝宝表情提供选择器专用的 128 像素缩略图，正文使用 256 像素压缩 WebP，保留透明底；面板按需加载小图，避免一次下载整套高清图片。","Waline 与听雨茶室同步新增独立的“岸宝”表情分组，18 张表情保留白蓝手绘人物，搭配灰蓝短字与小图案，包含探头、躺平、心虚、思考、偷笑、没电、催更、递茶等小场景；共用本地 WebP 素材、128 像素缩略图和悬停放大预览，电脑和手机端均将岸宝排在首位。","茶室中的岸宝和尤诺宝宝共 36 个表情，点击后立即作为独立消息发送，保留输入框中的文字、待发图片和提及；发送失败可单独重试，重复请求不会产生多条消息。内置表情无需等待 AI 文字审核，不占图片额度，仍受禁言、发送间隔和消息频率限制；前后端表情清单同步更新。","Waline 与茶室的图片表情支持悬停放大预览，也可用键盘聚焦查看；圆角浮动预览框避开屏幕边缘，并在移开、滚动或切换分类时关闭。大图只在需要预览时加载。","聊天消息和评论正文中的表情支持单击放大，手机点一下即可查看；表情名称位于大图下方居中，支持关闭按钮、点击遮罩及键盘退出。预览区域预留固定尺寸，加载提示叠在图片区，避免图片载入或提示消失时弹窗和名称跳动。","聊天气泡参考微信调整：头像与气泡顶边对齐，双方消息分别靠左右排布，长消息在另一侧同样预留头像与间距的位置，保持左右留白对称；气泡随内容伸缩并加入朝向头像的小尖角。手机端收起重复的操作按钮和额外标签，回复与回应等操作通过长按消息打开；单独发送的表情使用透明背景。","进入茶室时先完成聊天记录加载、输入区布局和阅读位置恢复，再显示消息，减少记录先出现再上下跳动的情况；带未读消息进入时保留未读定位，连接失败时正常显示提示。","文字草稿和待发送图片保存在当前浏览器，按身份隔离，刷新后恢复；发送失败在消息旁显示重试，重试沿用原消息编号、引用和提及，避免重复发送。手机搜索入口收进输入区工具栏，保留原有设置和在线人数小圆按钮。","茶室 @ 邮件提醒改为浅粉蓝圆角卡片，加入撑伞小猫、发送者信息、消息原文、北京时间和返回茶室的胶囊按钮；小猫随邮件内嵌，保留纯文本及可复制链接，并适配手机邮箱。"]', '86,85,84,83,82,80', '2026-11-07 12:00:00', '2026-11-07 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (82, 'V4.4.2', '2026-11-09', 'feature', '茶室身份与运营完善', '统一茶室身份，补齐通知、置顶与管理体验', '统一邮箱进入和 Waline 验证后的茶室资料，新增退出、浏览器通知、消息置顶，并优化记录管理、移动搜索和服务诊断。', '["听雨茶室","账号身份","浏览器通知","消息置顶","后台管理"]', '["同一邮箱资料和 Waline 身份会尽量沿用同一份茶室身份、头像、标签和聊天记录；不同登录方式的会话权限分别保存，退出茶室不会退出评论区账号。","后台补充聊天记录分页缓存、批量管理和服务诊断；移动端清理重复搜索入口，表情选择器也放大了预览尺寸。","个人设置支持后台浏览器通知；站长可以置顶有效消息，在线页面通过同步事件更新置顶栏，撤回、删除或删除作者时自动解除。","同步聊天服务的认证策略、健康检查和静态发布等待逻辑，修复部署重启后的状态判断，并完成依赖安全维护。","友链批量变更继续通过小爱后台提交，保留提交版本校验和发布状态核对。"]', '86,85,84,83,81,80', '2026-11-09 12:00:00', '2026-11-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (83, 'V4.5.0', '2026-11-09', 'feature', '茶室 Markdown 与语音更新', '聊天消息支持 Markdown、语音和个人阅读设置', '听雨茶室可以写 Markdown 小文章了，新增标题、列表、引用、表格、代码高亮与复制，也加入语音消息和个人阅读偏好。', '["听雨茶室","Markdown","语音消息","个人设置","代码高亮"]', '["聊天正文支持标题、粗体、斜体、删除线、链接、有序列表、无序列表、引用、表格、分隔线和行内代码；HTML 仍作为普通文字处理。","代码块支持常见语言高亮，并提供复制按钮；单条消息继续保留长度限制，长文章可以继续发布在博客中。","新增语音消息录制、取消、发送、播放、暂停和进度显示，服务端保存时校验格式、时长和文件大小，失败时保留可重试状态。","个人设置新增浏览器通知、消息提示音、拍一拍提示音、免打扰时段、聊天字号、消息间距和图片自动加载偏好。","同步发布听雨茶室 Markdown 更新文章，补充账号资料统一、退出入口、浏览器提醒、消息置顶、表情面板和后台管理优化说明。"]', '86,85,84,82,81,80', '2026-11-09 12:00:00', '2026-11-09 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (84, 'V4.5.1', '2026-11-10', 'fix', '聊天问题修复', 'Markdown 图片现在可以直接显示', '修复 Markdown 图片只显示链接的问题，安全的 HTTP/HTTPS 图片会在聊天气泡中直接展示，并可点击查看原图。', '["听雨茶室","Markdown","图片消息","安全修复"]', '["Markdown 图片语法现在会生成独立的图片节点，不再退化为“[图片] 图片地址”的普通链接。","图片地址仍经过 HTTP/HTTPS 校验，拒绝 JavaScript、data、带账号密码和包含控制字符的地址；图片使用懒加载、无来源头，并限制最大显示尺寸。","图片可以点击打开原图，原有的图片按钮、粘贴和拖动上传功能保持不变。"]', '86,85,83,82,81,80', '2026-11-10 12:00:00', '2026-11-10 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (85, 'V4.5.2', '2026-11-10', 'feature', '茶室互联与体验更新', '茶室接入 Matrix 互联，完善独立身份、表情与聊天体验', '新增 Matrix 互联、独立发言身份与短编号，补齐头像和动态表情同步、撤回删除、来源提示与消息排版，并修复构建检查和服务部署问题。', '["听雨茶室","Matrix 互联","独立身份","动态表情","消息排版","构建部署","友链"]', '["搭建本站 Matrix 节点，将听雨茶室接入 Detached 的聊天大厅；新增文字双向同步、引用回复、撤回映射、持久队列、断线补齐与去重，不重新发布启用前的聊天历史。","茶友在互联房间中使用各自的独立身份发言，显示茶室昵称和头像，无需另外注册或登录 Matrix；邮箱、登录会话与管理权限不会随消息公开。","独立身份改用 zzty001、zzty002 等顺序短编号，编号及对应关系持久保存，服务重启后继续沿用；已使用的长身份迁移时保留昵称、头像和旧消息，旧消息仍可撤回。","补齐双向头像同步：Matrix 成员头像可同步到茶室，茶友在本站修改昵称或头像后，也会更新自己的 Matrix 发言身份；未设置头像时沿用默认小猪头像。","支持将茶室的 367 个内置自定义表情发送到 Matrix，其中 111 个精选和 QQ 动态表情保留动画；单独发送显示为贴纸，夹在文字中的表情显示为图片，不再只出现内部编号。","表情上传结果可跨访客和服务重启复用，失败后保留队列重试；贴纸回复、撤回与重复消息识别同步适配，已撤回的贴纸不会再被误判为媒体发送失败。","补上从本站 Matrix 账号导入的本人消息删除同步；其他站点账号的导入消息仍只在本站删除，不借用他人身份操作外站内容。","后台聊天记录区分用户自行撤回和管理员删除：前者显示“某某撤回了一条消息”和“已撤回”，不再统一标成“管理员删除”。","统一跨站消息、历史记录、茶友资料和管理名单的来源标签。茶室互联提示增加 Detached 与 AIOVTUE-雪 的金色链接，点击可进入对应聊天室，并适配手机端换行和连接状态提示。","消息头像改为与昵称行顶部对齐，引用回复、长消息和本人右侧消息使用一致的排布。","修正昵称相对身份标签略微下沉的问题，昵称和标签垂直居中，保留站长与推荐友链的昵称样式。","修复 Markdown 正文没有继承聊天字号的问题，默认正文由实际显示的 16px 调整为设置中的 14px；列表、引用和发送中消息也会跟随个人字号。","核对电脑、手机、紧凑模式和自定义字号，长昵称及来源标签换行时保持正常显示。","修复构建检查漏装聊天服务独立依赖，导致两项 SMTP 测试失败、整次工作流显示失败的问题。","增强聊天服务部署对构建连接异常的恢复能力，只对已识别的连接故障有限重试；新镜像构建完成后再更新服务，并核对健康状态与发布版本。","通过小爱后台新增友链“呓语集”，补充站点头像、订阅和主页预览资料；友链订阅与连通性快照继续自动刷新。","互联范围以实际接入为准：当前连接记录已确认 Detached 大厅，Daily 仍待对方适配接入；图片、语音及 Matrix 端外来贴纸的入站同步尚未开放。"]', '86,84,83,82,81,80', '2026-11-10 12:00:00', '2026-11-10 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (86, 'V4.6.0', '2026-11-13', 'feature', '茶室互联与点歌台更新', '完善茶室跨站互联与点歌台，支持歌单精选播放', '继续完善 Matrix 消息互通、成员状态和跨站提及体验；点歌台新增外部歌单导入与共享、全室精选播放和历史管理。', '["听雨茶室","Matrix 互联","跨站提及","引用跳转","点歌台","歌单共享","精选播放"]', '["继续完善茶室与 Matrix 聊天室的消息互通：茶室图片可转发到 Matrix，Matrix 图片和贴纸可同步进入茶室；补充成员头像与在线状态同步，并区分外站撤回和管理员删除。","改善茶室消息浏览：点击引用可跳回原消息并短暂高亮；增加定位最新消息的提示和动画；跨站 @ 保留被提及者的身份与来源，成员选择器支持浏览完整名单。","点歌台新增歌单页，可粘贴 Playlist Out 歌单链接导入 QQ 音乐、网易云、酷狗、酷我、汽水和咪咕歌单。导入内容和来源链接保存在茶室中，个人歌单可分享给茶友，也可从原链接刷新。","QQ 音乐歌单沿用原曲目编号；其他平台的歌曲按歌名和歌手匹配 QQ 曲库，标记可播放曲目，未匹配成功的歌曲仍可在茶室内搜索。","增加点歌历史和管理员播放设置。站长可以从自己的个人歌单或茶友共享歌单中设置全室精选，并在点歌台设置中选择循环精选或常驻歌单；切换播放源时保留当前歌曲和茶友已点歌曲。","精选保存来源中匹配成功且可播放的歌曲，不再受 100 首限制；队列仍最多容纳 100 首，并会在歌曲播放后自动补入后续精选曲目。","优化点歌台布局：五个导航等宽铺满，顺序调整为歌词、搜索、已点、歌单、历史；播放器放在导航下方，只在歌词页显示，切换页面不会中断播放。"]', '85,84,83,82,81,80', '2026-11-13 12:00:00', '2026-11-13 12:00:00');
INSERT INTO changelog (id, version, log_date, tone, kind, title, summary, topics, details, related_ids, create_time, update_time) VALUES (87, 'V3.1.0', '2026-11-18', 'feature', '博客功能与编辑器更新', '新增博客更新日志页，完善编辑器工具栏与内容渲染', '新增时间线与关系图双视图的更新日志页；补齐编辑器工具栏按钮、joe 组件与富文本排版，修复移动端图片混合内容显示。', '["更新日志","编辑器工具栏","JOE 组件","富文本排版","移动端"]', '["新增「更新日志」页面：提供时间线与关系图两种视图，支持详情弹窗、相关更新跳转和五种更新类型图例，深浅色与窄屏均可正常使用。","更新日志按参考站实测样式复刻：介绍区、带左侧色条的栏目标题、时间线圆点与连线、关系图五列卡片与曲线连接，均沿用同一套排版与配色。","文章富文本排版照搬参考站样式，正文、标题、引用、列表、代码块与表格的字号和间距统一。","编辑器移植 joe2.0 组件：bilibili 嵌入、歌单、单曲、多彩按钮、便条、彩色分割线、隐藏、卡片、消息提示、进度条、标签栏、时间轴、点击复制、跑马灯、折叠内容、网盘下载，并接入本地运行时资源；表情继续使用站内微博、哔哩哔哩、bmoji 三组图片表情。","编辑器工具栏按参考图补齐「已完成」「备注」「下载」「发布」，统一按钮名称与顺序，保留下划线、下标、上标、美化、目录；预览区可正常插入对应元素。","撤除机型标签，补上苹果标，修复移动端图片混合内容不显示的问题。"]', '', '2026-11-18 12:00:00', '2026-11-18 12:00:00');
